gold.schema_ddl:
CREATE TABLE fatture (
    id INT PRIMARY KEY,
    numero_fattura TEXT NOT NULL UNIQUE,
    data_fattura DATE NOT NULL,
    importo_totale NUMERIC(12,2) CHECK (importo_totale >= 0),
    descrizione TEXT
);

CREATE TABLE pagamenti (
    id INT PRIMARY KEY REFERENCES fatture(id),
    data_pagamento DATE NOT NULL,
    importo_pagato NUMERIC(12,2) CHECK (importo_pagato >= 0),
    metodo_pagamento TEXT
);
